import java.util.*;import java.util.zip.*;import java.nio.file.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Patch implements Opcodes {public static void main(String[] args)throws Exception{Map<String,byte[]> data=new TreeMap<>();int guards=0,visible=0,transforms=0;try(ZipFile z=new ZipFile(args[0])){for(ZipEntry entry:Collections.list(z.entries())){byte[] b=z.getInputStream(entry).readAllBytes();if(entry.getName().equals("dev/zomboid/isotacz/Bridge.class")||entry.getName().endsWith("/AbstractRenderContextMixin2.class")){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);for(MethodNode m:c.methods){if(c.name.equals("dev/zomboid/isotacz/Bridge")&&m.name.equals("open")){for(AbstractInsnNode i:m.instructions.toArray())if(i instanceof MethodInsnNode call&&call.owner.equals("dev/zomboid/isotacz/BackpackInteraction")&&call.name.equals("open")){call.owner="dev/zomboid/isotacz/NativeInteraction";guards++;}}if(c.name.equals("dev/zomboid/isotacz/Bridge")&&m.name.equals("mouse")){InsnList l=new InsnList();l.add(new VarInsnNode(LLOAD,0));l.add(new VarInsnNode(ILOAD,2));l.add(new VarInsnNode(ILOAD,3));l.add(new VarInsnNode(ILOAD,4));l.add(new VarInsnNode(ALOAD,5));l.add(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/isotacz/NativeInteraction","mouse","(JIIILjava/lang/Object;)Z",false));LabelNode normal=new LabelNode();l.add(new JumpInsnNode(IFEQ,normal));l.add(new InsnNode(RETURN));l.add(normal);l.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(l);visible++;}if(c.name.endsWith("/AbstractRenderContextMixin2")&&m.name.equals("hasTransformXIV")){m.instructions.clear();m.tryCatchBlocks.clear();if(m.localVariables!=null)m.localVariables.clear();m.instructions.add(new InsnNode(RETURN));transforms++;}}ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);b=w.toByteArray();}data.put(entry.getName(),b);}}if(guards!=1||visible!=1||transforms!=1)throw new IllegalStateException("Missing view hooks: "+guards+" "+visible);try(var files=Files.walk(Path.of(args[2]))){for(Path f:files.filter(Files::isRegularFile).toList())data.put(Path.of(args[2]).relativize(f).toString(),Files.readAllBytes(f));}data.put("META-INF/neoforge.mods.toml",new String(data.get("META-INF/neoforge.mods.toml")).replace("3.6.2+zomboid.21","3.6.2+zomboid.22").getBytes());int methods=0;for(var e:data.entrySet())if(e.getKey().endsWith(".class")){ClassNode c=new ClassNode();new ClassReader(e.getValue()).accept(c,0);for(MethodNode m:c.methods)if((m.access&(ACC_ABSTRACT|ACC_NATIVE))==0){new Analyzer<>(new BasicVerifier()).analyze(c.name,m);methods++;}}try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(args[1])))){for(var e:data.entrySet()){z.putNextEntry(new ZipEntry(e.getKey()));z.write(e.getValue());z.closeEntry();}}System.out.println("Isometric view methods checked: "+methods);}}
